import{_ as e,c as o,o as i,b2 as a}from"./chunks/framework.CUhoHPxN.js";const m=JSON.parse('{"title":"Excel 工具类设计方案（quickboot-common）","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-10-excel-tool-design.md","filePath":"superpowers/specs/2026-05-10-excel-tool-design.md"}'),c={name:"superpowers/specs/2026-05-10-excel-tool-design.md"};function t(d,l,r,n,s,h){return i(),o("div",null,[...l[0]||(l[0]=[a('<h1 id="excel-工具类设计方案-quickboot-common" tabindex="-1">Excel 工具类设计方案（quickboot-common） <a class="header-anchor vp-link" href="#excel-工具类设计方案-quickboot-common" aria-label="Permalink to &quot;Excel 工具类设计方案（quickboot-common）&quot;">​</a></h1><h2 id="_1-目标与边界" tabindex="-1">1. 目标与边界 <a class="header-anchor vp-link" href="#_1-目标与边界" aria-label="Permalink to &quot;1. 目标与边界&quot;">​</a></h2><h3 id="_1-1-目标" tabindex="-1">1.1 目标 <a class="header-anchor vp-link" href="#_1-1-目标" aria-label="Permalink to &quot;1.1 目标&quot;">​</a></h3><ol><li>对标 RuoYi/quick-boot 的完整 Excel 能力：监听器、校验、合并、模板、字典翻译、失败明细、策略模型。</li><li>能力统一下沉至 <code>quickboot-common</code>，供后续所有业务模块复用。</li></ol><h3 id="_1-2-边界" tabindex="-1">1.2 边界 <a class="header-anchor vp-link" href="#_1-2-边界" aria-label="Permalink to &quot;1.2 边界&quot;">​</a></h3><ol><li>工具层不负责批量写库，由业务层决定并实现。</li><li>重复语义不在工具层硬编码，由业务层定义（如库内重复、文件内重复、组合唯一等）。</li><li>继续沿用当前技术路线：<code>EasyExcel + Jakarta Validation</code>。</li></ol><h2 id="_2-模块结构设计" tabindex="-1">2. 模块结构设计 <a class="header-anchor vp-link" href="#_2-模块结构设计" aria-label="Permalink to &quot;2. 模块结构设计&quot;">​</a></h2><p>建议在 <code>quickboot-common/src/main/java/io/github/genkidoudou/common/excel</code> 下按职责拆分：</p><ol><li><code>core</code></li></ol><ul><li><code>EasyExcelSupport</code>：读写入口、响应输出、模板输出、字节流输出。</li><li><code>ExcelImportEngine</code>：统一导入执行器（策略驱动）。</li></ul><ol start="2"><li><code>model</code></li></ol><ul><li><code>ExcelImportContext</code>：导入上下文（策略、扩展参数、校验开关等）。</li><li><code>ExcelImportStrategy</code>：统一策略枚举（如 <code>IGNORE</code> / <code>OVERWRITE</code>）。</li><li><code>ExcelImportResult</code>：总数、成功数、失败数、失败行号、失败文件等。</li><li><code>ExcelImportErrorRow</code>：错误行号、错误列、错误原因。</li></ul><ol start="3"><li><code>listener</code></li></ol><ul><li><code>ExcelListener&lt;T&gt;</code>：监听器统一接口。</li><li><code>DefaultExcelListener&lt;T&gt;</code>：默认监听器（转换异常、validation 异常收集）。</li><li><code>DefaultExcelListenerCallback&lt;T&gt;</code>：逐行回调监听器。</li></ul><ol start="4"><li><code>annotation</code></li></ol><ul><li><code>ExcelDictFormat</code>：字典翻译注解（已存在，继续使用）。</li><li><code>CellMerge</code>：合并列注解。</li></ul><ol start="5"><li><code>convert</code></li></ol><ul><li><code>ExcelDictConverter</code>：字典值/标签双向转换。</li></ul><ol start="6"><li><code>merge</code></li></ol><ul><li><code>CellMergeStrategy</code>：按注解进行纵向合并。</li></ul><ol start="7"><li><code>exception</code></li></ol><ul><li><code>ExcelDataCheckException</code>：业务校验异常。</li><li><code>ExcelImportFieldException</code>：字段级错误（用于精确列名错误）。</li></ul><h2 id="_3-导入流程设计" tabindex="-1">3. 导入流程设计 <a class="header-anchor vp-link" href="#_3-导入流程设计" aria-label="Permalink to &quot;3. 导入流程设计&quot;">​</a></h2><ol><li>读取 <code>MultipartFile</code>，执行 <code>readSheetResult</code>。</li><li>Listener 层处理：</li></ol><ul><li>单元格类型转换异常。</li><li>Bean Validation 异常（你确认采用 validation + 业务校验并行）。</li></ul><ol start="3"><li>对每行调用业务 <code>RowHandler&lt;T&gt;</code>。</li><li>业务回调只做规则判断与分类，不做工具层批量写库。</li><li>引擎统一聚合结果并生成失败明细文件（可选）。</li></ol><h2 id="_4-导出流程设计" tabindex="-1">4. 导出流程设计 <a class="header-anchor vp-link" href="#_4-导出流程设计" aria-label="Permalink to &quot;4. 导出流程设计&quot;">​</a></h2><ol><li>普通导出：响应流写出。</li><li>模板导出：仅表头。</li><li>字典翻译导出：借助 <code>ExcelDictConverter</code>。</li><li>合并导出：注册 <code>CellMergeStrategy</code>。</li></ol><h2 id="_5-职责分层" tabindex="-1">5. 职责分层 <a class="header-anchor vp-link" href="#_5-职责分层" aria-label="Permalink to &quot;5. 职责分层&quot;">​</a></h2><h3 id="_5-1-工具层职责-common" tabindex="-1">5.1 工具层职责（common） <a class="header-anchor vp-link" href="#_5-1-工具层职责-common" aria-label="Permalink to &quot;5.1 工具层职责（common）&quot;">​</a></h3><ol><li>Excel 解析、监听、基础校验。</li><li>错误聚合、失败明细生成。</li><li>统一策略模型与导出能力。</li></ol><h3 id="_5-2-业务层职责-web" tabindex="-1">5.2 业务层职责（web） <a class="header-anchor vp-link" href="#_5-2-业务层职责-web" aria-label="Permalink to &quot;5.2 业务层职责（web）&quot;">​</a></h3><ol><li>重复语义定义。</li><li>新增/更新分类后的落库策略（单条/批量/分片）。</li><li>业务字段映射与领域异常语义。</li></ol><h2 id="_6-关键接口-语义" tabindex="-1">6. 关键接口（语义） <a class="header-anchor vp-link" href="#_6-关键接口-语义" aria-label="Permalink to &quot;6. 关键接口（语义）&quot;">​</a></h2><ol><li><code>ExcelImportEngine.importByCallback(...)</code></li></ol><ul><li>入参：<code>file</code>、<code>rowClass</code>、<code>context</code>、<code>rowHandler</code>、<code>columnLabelMapper</code>、<code>blankChecker</code></li><li>出参：<code>ExcelImportResult</code></li></ul><ol start="2"><li><code>RowHandler&lt;T&gt;</code></li></ol><ul><li>入参：<code>row</code>、<code>analysisContext</code>、<code>stats</code></li><li>约定：可抛 <code>ExcelImportFieldException(field, message)</code>。</li></ul><ol start="3"><li><code>ExcelImportContext</code></li></ol><ul><li><code>strategy</code>：<code>IGNORE</code> / <code>OVERWRITE</code></li><li><code>validate</code>：是否启用 Bean Validation</li><li><code>ext</code>：扩展参数（如 <code>dictType</code>）</li><li><code>errorFileName</code>：失败文件名</li></ul><h2 id="_7-错误处理与失败明细" tabindex="-1">7. 错误处理与失败明细 <a class="header-anchor vp-link" href="#_7-错误处理与失败明细" aria-label="Permalink to &quot;7. 错误处理与失败明细&quot;">​</a></h2><ol><li>解析异常：记录行号、列号、表头、异常原因。</li><li>validation 异常：记录行号和校验消息。</li><li>业务异常：</li></ol><ul><li>抛 <code>ExcelImportFieldException</code> 标注字段。</li><li>通过 <code>columnLabelMapper</code> 映射中文列名。</li></ul><ol start="4"><li>失败明细统一 sheet：<code>导入失败明细</code>，字段为：</li></ol><ul><li><code>错误行号</code></li><li><code>错误列</code></li><li><code>错误原因</code></li></ul><h2 id="_8-字典模块接入策略" tabindex="-1">8. 字典模块接入策略 <a class="header-anchor vp-link" href="#_8-字典模块接入策略" aria-label="Permalink to &quot;8. 字典模块接入策略&quot;">​</a></h2><ol><li><code>dict type</code> / <code>dict data</code> 作为首个接入样板。</li><li>Service 保留：</li></ol><ul><li>行级规则判断。</li><li>行分类（新增/更新/失败）。</li><li>导入完成后业务后处理（如刷新缓存）。</li></ul><ol start="3"><li>与现有对外接口保持兼容。</li></ol><h2 id="_9-测试策略" tabindex="-1">9. 测试策略 <a class="header-anchor vp-link" href="#_9-测试策略" aria-label="Permalink to &quot;9. 测试策略&quot;">​</a></h2><h3 id="_9-1-common-单测" tabindex="-1">9.1 common 单测 <a class="header-anchor vp-link" href="#_9-1-common-单测" aria-label="Permalink to &quot;9.1 common 单测&quot;">​</a></h3><ol><li>listener 校验路径：类型转换、validation、业务异常。</li><li><code>ExcelImportResult</code> 聚合正确性。</li><li>失败明细文件生成正确性。</li><li>字典转换器双向一致性。</li><li>合并策略边界行为。</li></ol><h3 id="_9-2-web-集成测试" tabindex="-1">9.2 web 集成测试 <a class="header-anchor vp-link" href="#_9-2-web-集成测试" aria-label="Permalink to &quot;9.2 web 集成测试&quot;">​</a></h3><ol><li><code>IGNORE</code> / <code>OVERWRITE</code> 策略分支。</li><li>失败明细中行号/列/原因准确。</li><li>模板下载与导出链路可用。</li></ol><h2 id="_10-迁移与落地顺序" tabindex="-1">10. 迁移与落地顺序 <a class="header-anchor vp-link" href="#_10-迁移与落地顺序" aria-label="Permalink to &quot;10. 迁移与落地顺序&quot;">​</a></h2><ol><li>在 <code>quickboot-common</code> 固化完整工具能力。</li><li>字典模块完成接入与回归验证。</li><li>逐步迁移其它业务模块导入导出。</li><li>过渡期可保留旧方法并标记废弃，迁移完成后统一收敛。</li></ol><h2 id="_11-验收标准" tabindex="-1">11. 验收标准 <a class="header-anchor vp-link" href="#_11-验收标准" aria-label="Permalink to &quot;11. 验收标准&quot;">​</a></h2><ol><li><code>quickboot-common</code> 提供完整可复用 Excel 导入导出工具。</li><li>字典模块接入后满足既有功能与新增要求（失败明细、字段级错误列、策略模型）。</li><li>工具层不做批量写库，业务层可自由实现批量策略。</li><li>能力文档齐全，后续业务可按模板快速接入。</li></ol>',58)])])}const p=e(c,[["render",t]]);export{m as __pageData,p as default};
